-- S0: S1 with 5,000 rows of five other layers and 600 earthview rows finished before the read range. 5888 rows in the table, 288 in the read range.
WITH RECURSIVE n(i) AS (SELECT 0 UNION ALL SELECT i + 1 FROM n WHERE i < 287) INSERT INTO collector_runs (layer, started_at, finished_at, status, http_status, records, bytes, note) SELECT 'earthview', strftime('%Y-%m-%dT%H:%M:%fZ', 1795316400 + i * 600, 'unixepoch'), strftime('%Y-%m-%dT%H:%M:%fZ', 1795316400 + i * 600 + 15, 'unixepoch'), 'ok', 200, 0, 0, 'nothing newer: fixture frame' FROM n;
WITH RECURSIVE n(i) AS (SELECT 0 UNION ALL SELECT i + 1 FROM n WHERE i < 4999) INSERT INTO collector_runs (layer, started_at, finished_at, status, http_status, records, bytes, note) SELECT CASE i % 5 WHEN 0 THEN 'usgs' WHEN 1 THEN 'firms' WHEN 2 THEN 'ships' WHEN 3 THEN 'swpc' ELSE 'wind' END, strftime('%Y-%m-%dT%H:%M:%fZ', 1795316400 + i * 34, 'unixepoch'), strftime('%Y-%m-%dT%H:%M:%fZ', 1795316400 + i * 34 + 3, 'unixepoch'), 'ok', 200, 10, 1000, 'fixture: another layer' FROM n;
WITH RECURSIVE n(i) AS (SELECT 0 UNION ALL SELECT i + 1 FROM n WHERE i < 599) INSERT INTO collector_runs (layer, started_at, finished_at, status, http_status, records, bytes, note) SELECT 'earthview', strftime('%Y-%m-%dT%H:%M:%fZ', 1795316400 - 600 * (i + 1), 'unixepoch'), strftime('%Y-%m-%dT%H:%M:%fZ', 1795316400 - 600 * (i + 1) + 15, 'unixepoch'), 'ok', 200, 0, 0, 'nothing newer: fixture, before the range' FROM n;
